        <section class="ticket-footer">
          <div class="ticket-seller">VENDEDOR</div>
          <div class="ticket-footer-block">
            <div class="ticket-footer-line">
              <span>TOTAL :</span>
              <span>{{ money(ticket.total) }}</span>
