      <aside v-if="evidenceImages.length > 0" class="ticket-evidence-panel" :class="{ 'evidence-hidden-print': !printWithEvidence }">
        <h3 class="ticket-evidence-title">Evidencias de pago</h3>
        <div v-for="(img, idx) in evidenceImages" :key="idx" class="ticket-evidence-item">
          <img :src="img.url" :alt="'Evidencia ' + (idx + 1)" class="ticket-evidence-img" />
          <p class="ticket-evidence-method">{{ img.method }}</p>
          <p v-if="img.amount > 0" class="ticket-evidence-amount">{{ money(img.amount) }}</p>
        </div>
      </aside>
    </div>
  </div>
</template>

<script>
import {
  loadPosTicketData,
  formatTicketMoneyWithSymbol,
  formatTicketDate,
  buildInvoiceNumber,
  mergeTicketCompany,
  resolveCompanyLogoUrl,
} from "@/utils/posTicketPrint";
import settingsService from "@/services/settings.service";
import remissionsService from "@/services/remissions.service";
import mediaService from "@/services/media.service";

const body = document.getElementsByTagName("body")[0];

export default {
  name: "PosTicket",
  data() {
    return {
      ticket: null,
      loading: true,
      printWithEvidence: false,
      mediaDocs: [],
    };
  },
  computed: {
    companyLine() {
      const name = this.ticket?.company?.company_name || "MI STOCK";
      return String(name).toUpperCase();
    },
    customerName() {
      return String(this.ticket?.client?.name || "CONSUMIDOR FINAL").toUpperCase();
    },
    documentLine() {
      const type = this.ticket?.client?.document_type || "CC";
      const doc = this.ticket?.client?.document || "—";
      return `${type} No. : ${doc}`;
    },
    phoneLine() {
      const phone = this.ticket?.client?.phone;
      if (!phone) return "";
      return `Tel.: ${phone}`;
    },
    locationLine() {
      const parts = [this.ticket?.client?.province, this.ticket?.client?.city].filter(Boolean);
      if (!parts.length) return "";
      return parts.join(" / ");
    },
    addressLine() {
      const address = this.ticket?.client?.address;
      if (!address) return "";
      return `Dirección: ${address}`;
    },
    logoUrl() {
      return resolveCompanyLogoUrl(this.ticket?.company);
    },
    paymentRows() {
      if (!this.ticket) return [];
      // Si hay pagos reales registrados, listarlos individualmente
      if (Array.isArray(this.ticket.payments) && this.ticket.payments.length > 0) {
        return this.ticket.payments.map((p) => ({
          method: String(p.payment_method || "EFECTIVO").toUpperCase(),
          amount: Number(p.amount || 0),
        }));
      }
      // Si no hay pagos registrados pero se recibió monto, mostrar una sola fila
      if (Number(this.ticket.received) > 0) {
        return [{ method: String(this.ticket.paymentMethod || "EFECTIVO").toUpperCase(), amount: Number(this.ticket.received) }];
      }
      return [];
    },
    evidenceImages() {
      const base = process.env.VUE_APP_API_IMAGE_URL || '';
      const images = [];

      // Evidencias de pago (con evidence_path)
      if (this.ticket && Array.isArray(this.ticket.payments)) {
        this.ticket.payments
          .filter(p => p.evidence_path)
          .forEach(p => {
            images.push({
              url: base + encodeURI(p.evidence_path),
              method: String(p.payment_method || "EFECTIVO").toUpperCase(),
              amount: Number(p.amount || 0),
            });
          });
      }

      // Documentos media (imágenes subidas como evidencias)
      if (Array.isArray(this.mediaDocs)) {
        this.mediaDocs
          .filter(d => {
            const ext = (d.file_path || '').split('.').pop().toLowerCase();
            return ['jpg', 'jpeg', 'png', 'gif', 'svg', 'webp'].includes(ext);
          })
          .forEach(d => {
            images.push({
              url: base + encodeURI(d.file_path),
              method: 'Evidencia',
              amount: 0,
            });
          });
      }

      return images;
    },
  },
  methods: {
    money(value) {
      return formatTicketMoneyWithSymbol(value);
    },
    formatQty(qty) {
      const n = Number(qty) || 0;
      return Number.isInteger(n) ? String(n) : n.toLocaleString("es-CO", { maximumFractionDigits: 2 });
    },
    itemLabel(item) {
      const name = String(item.name || "").toUpperCase();
      const suffix = item.ref ? ` (${item.ref})` : " (Und)";
      return name + suffix;
    },
    printTicket(withEvidence = false) {
      this.printWithEvidence = withEvidence;
      if (withEvidence) {
        document.body.classList.add('print-with-evidence');
      } else {
        document.body.classList.remove('print-with-evidence');
      }
      this.$nextTick(() => {
        window.print();
        // Limpiar después de imprimir
        document.body.classList.remove('print-with-evidence');
      });
    },
    closeTicket() {
      window.close();
      if (!window.closed) {
        this.$router.push({ name: "POS" });
      }
    },
    async fetchCompanySettings() {
      try {
        const settingsRes = await settingsService.get();
        return settingsRes.data || {};
      } catch (e) {
        console.error("No se pudo cargar configuración:", e);
        return {};
      }
    },
    async loadMediaDocs(remissionId) {
      try {
        const res = await mediaService.getData(remissionId);
        this.mediaDocs = (res.data || []).filter(item => item.mediaable_type === 'remission');
      } catch (e) {
        console.error("Error al cargar documentos media:", e);
        this.mediaDocs = [];
      }
    },
    buildTicketFromRemission(r, company) {
      const items = (r.details || []).map((d) => ({
        name: String(d.inventory?.name || "PRODUCTO").toUpperCase(),
        ref: d.inventory?.ref || null,
        color: d.variant?.color?.name || "",
        talla: d.variant?.size?.size || "",
        quantity: d.quantity,
        unitPrice: d.unit_price,
        total: d.total,
      }));
      const articlesCount = items.reduce((sum, i) => sum + Number(i.quantity || 0), 0);
      const total = Number(r.grand_total || r.total || 0);
      // Calcular el total pagado a partir de los pagos reales (preferido) o amount_paid
      const paymentsTotal = Array.isArray(r.payments)
        ? r.payments.reduce((sum, p) => sum + Number(p.amount || 0), 0)
        : 0;
      const received = paymentsTotal > 0
        ? paymentsTotal
        : (Number(r.amount_paid) > 0 ? Number(r.amount_paid) : 0);
      const change = Math.max(0, received - total);
      const pending = Math.max(0, total - received);
      const isFullyPaid = received >= total;
      return mergeTicketCompany({
        remissionId: r.id,
        invoiceNo: buildInvoiceNumber(r.id),
        dateFormatted: formatTicketDate(r.created_at),
        client: {
          id: r.user?.id || null,
          name: r.user?.name || r.name || "CONSUMIDOR FINAL",
          document_type: r.user?.document_type || "CC",
          document: r.user?.document || r.document || String(r.user?.id || ""),
          phone: r.user?.phone || r.phone || "",
          address: r.user?.address || r.address || "",
          province: r.user?.province || "",
          city: r.user?.city || "",
        },
        items,
        subtotal: Number(r.subtotal || 0),
        itemsTotal: items.reduce((sum, i) => sum + Number(i.total || 0), 0),
        discountAmount: Number(r.discount_amount || 0),
        flete: Number(r.flete || 0),
        giftValue: Number(r.gift_value || 0),
        total,
        received,
        change,
        pending,
        isFullyPaid,
        payments: Array.isArray(r.payments) ? r.payments : [],
        paymentMethod: r.payment_method || "EFECTIVO",
        articlesCount,
        itemsCount: items.length,
        seller: String(r.seller?.name || "LOCAL").toUpperCase(),
        company: company || {},
      }, company);
    },
    async loadTicket() {
      this.loading = true;
      const remissionId = this.$route.query.id;
      try {
        const company = await this.fetchCompanySettings();
        // La API es la fuente de verdad cuando hay remissionId: siempre consulta
        // primero la API para garantizar color/talla completos para cualquier usuario.
        if (remissionId) {
          try {
            const res = await remissionsService.getData(remissionId);
            this.ticket = this.buildTicketFromRemission(res.data, company);
            await this.loadMediaDocs(remissionId);
            return;
          } catch (apiErr) {
            console.warn("No se pudo cargar el ticket desde la API, usando cache local:", apiErr);
            // Fallback al cache solo si la API falla
            const cached = loadPosTicketData(remissionId);
            if (cached) {
              this.ticket = mergeTicketCompany(cached, company);
              await this.loadMediaDocs(remissionId);
              return;
            }
            this.ticket = null;
            return;
          }
        }
        // Sin remissionId: usar cache local (ticket sin remisión asociada)
        const cached = loadPosTicketData();
        if (cached) {
          this.ticket = mergeTicketCompany(cached, company);
          return;
        }
        this.ticket = null;
      } catch (e) {
        console.error("Error al cargar ticket:", e);
        this.ticket = null;
      } finally {
        this.loading = false;
      }
    },
  },
  async mounted() {
    this.$store.state.hideConfigButton = true;
    this.$store.state.showSidenav = false;
    this.$store.state.showNavbar = false;
    this.$store.state.showFooter = false;
    body.classList.remove("g-sidenav-show");
    await this.loadTicket();
  },
  beforeUnmount() {
    this.$store.state.hideConfigButton = false;
    this.$store.state.showSidenav = true;
    this.$store.state.showNavbar = true;
    this.$store.state.showFooter = true;
    body.classList.add("g-sidenav-show");
  },
};
</script>

