<script>
import Sidenav from "./examples/Sidenav";
import Configurator from "@/examples/Configurator.vue";
import Navbar from "@/examples/Navbars/Navbar.vue";
import AppFooter from "@/examples/Footer.vue";
import { mapMutations } from "vuex";
import Swal from 'sweetalert2';
import * as bootstrap from 'bootstrap';


export default {
  name: "App",
  data() {
    return {
      category: {
        id: 0,
        code: '',
        name: '',
        description: '',
        parent_id: ''
      },
      categorySearch: '',
      categoryPage: {
        data: [],
        current_page: 1,
        from: 0,
        to: 0,
        total: 0,
        per_page: 10,
        last_page: 1,
        prev_page_url: null,
        next_page_url: null,
        links: [],
      },
      categoryPerPage: 10,
      collection: {
        id: 0,
        code: '',
        name: '',
        description: '',
      },
      collectionSearch: '',
      collectionPage: {
        data: [],
        current_page: 1,
        from: 0,
        to: 0,
        total: 0,
        per_page: 10,
        last_page: 1,
        prev_page_url: null,
        next_page_url: null,
        links: [],
      },
      collectionPerPage: 10,
      color: {
        id: 0,
        name: '',
        ref: ''
      },
      oficio: {
        id: 0,
        name: '',
        description: '',
        status: 1,
      },
      bodega: {
        id: 0,
        name: '',
        description: '',
        status: 1,
      },
      sizeList: {
        id: 0,
        size: ''
      },
      categories: [],
      collections: [],
      parents: [],
      colors: [],
      oficios: [],
      bodegas: [],
      tallas: [],
    }
  },
  components: {
    Sidenav,
    Configurator,
    Navbar,
    AppFooter
  },
  watch: {
    '$route.path'(path) {
      const isCatalog = path.startsWith('/catalogo/');
      this.$store.state.showSidenav = !isCatalog;
      this.$store.state.showNavbar = !isCatalog;
      this.$store.state.showFooter = !isCatalog;
    },
  },
  methods: {
    ...mapMutations(["toggleConfigurator", "navbarMinimize"]),
    closeModalCategory() {
      const configurator = this.$refs.configurator;
      if (configurator) {
        configurator.closeModalCategory(); // Llama al método para cerrar el modal
      }
    },
    openCategoryForm() {
      this.isEditingCategory = false;
      this.resetCategoryForm();
      const modal = new bootstrap.Modal(document.getElementById('ModalCategoryForm'));
      modal.show();
    },
    resetCategoryForm() {
      this.category = {
        id: 0,
        code: '',
        name: '',
        description: '',
        parent_id: '',
      };
    },
    async submitCategory() {
      try {
        // Dispara la acción de Vuex para guardar la categoría
        const response = await this.$store.dispatch("categories/save", this.category);

        if (response && response.status >= 200 && response.status < 300) {
          // Cierra el modal del formulario
          const formModalEl = document.getElementById('ModalCategoryForm');
          const formModal = bootstrap.Modal.getInstance(formModalEl);
          if (formModal) formModal.hide();

          await Swal.fire({
            icon: 'success',
            title: '¡Éxito!',
            text: 'El registro ha sido guardado correctamente.',
            confirmButtonText: 'Aceptar',
            backdrop: true,
          });

          // Limpia el formulario y refresca la tabla paginada
          this.resetCategoryForm();
          this.isEditingCategory = false;
          await this.getCategoriesPaginated(this.categoryPage.current_page);
        } else {
          throw new Error(response.data.message || 'Error al guardar el registro');
        }

      } catch (error) {
        console.error("Error al crear el registro:", error);
        await Swal.fire({
          icon: 'error',
          title: 'Error',
          text: error.message || 'Error al guardar el registro',
        });
      }
    },
    async editCategory(value) {
      this.isEditingCategory = true;
      this.category = {
        id: value.id,
        code: value.code || '',
        name: value.name,
        description: value.description || '',
        parent_id: value.parent_id || '',
      };
      const modal = new bootstrap.Modal(document.getElementById('ModalCategoryForm'));
      modal.show();
    },
    async cancelEditCategory() {
      this.isEditingCategory = false;
      this.resetCategoryForm();
      const formModalEl = document.getElementById('ModalCategoryForm');
      const formModal = bootstrap.Modal.getInstance(formModalEl);
      if (formModal) formModal.hide();
    },
    async getCategories() {
      const response = await this.$store.dispatch("categories/getCategories");
      this.categories = response.data;
      this.categories.sort((a, b) => a.fullname.localeCompare(b.fullname));
      this.parents = this.categories.filter(category => category.parent_id === null);
    },
    async getCategoriesPaginated(page = 1) {
      try {
        const response = await this.$store.dispatch("categories/getPaginated", {
          page,
          per_page: this.categoryPerPage,
          search: this.categorySearch,
        });
        this.categoryPage = response.data;
      } catch (error) {
        console.error("Error al obtener categorías paginadas:", error);
      }
    },
    async searchCategories() {
      await this.getCategoriesPaginated(1);
    },
    async changeCategoryPage(page) {
      if (page < 1 || page > this.categoryPage.last_page) return;
      await this.getCategoriesPaginated(page);
    },
    async goToCategoryPage(link) {
      if (!link.url || link.active) return;
      // link.label puede venir como "&laquo;" o número; usamos la URL para extraer la página
      const url = new URL(link.url, window.location.origin);
      const page = parseInt(url.searchParams.get('page') || '1', 10);
      await this.getCategoriesPaginated(page);
    },
    parentName(parentId) {
      if (!parentId) return '';
      const parent = this.categories.find(c => c.id === parentId);
      return parent ? parent.name : '';
    },
    async deleteCategory(id) {
      const response = await this.$store.dispatch("categories/delete", id);

      if (response && response.status >= 200 && response.status < 300) {
        await Swal.fire(
          'Eliminado!',
          'El registro se ha sido eliminado correctamente.',
          'success'
        );
        await this.getCategoriesPaginated(this.categoryPage.current_page);
      } else {
        await Swal.fire({
          icon: 'error',
          title: 'Error',
          text: 'Error al eliminar el registro, esta asociado con otros registros',
