        configurator.closeModalTallas(); // Llama al método para cerrar el modal
      }
    },
  },
  computed: {
    isCatalogRoute() {
      return this.$route.path.startsWith('/catalogo/');
    },
    categoryPageLinks() {
      // Filtra los links "..." del paginador de Laravel para mostrarlos como disabled
      return (this.categoryPage.links || []).map(link => {
        // Limpia las flechas &laquo; &raquo; para mostrarlas como texto simple
        return link;
      });
    },
    navClasses() {
      return {
        "position-sticky bg-white left-auto top-2 z-index-sticky":
          this.$store.state.isNavFixed && !this.$store.state.darkMode,
        "position-sticky bg-default left-auto top-2 z-index-sticky":
          this.$store.state.isNavFixed && this.$store.state.darkMode,
        "position-absolute px-4 mx-0 w-100 z-index-2": this.$store.state
          .isAbsolute,
        "px-0 mx-4": !this.$store.state.isAbsolute
      };
    }
  },
  beforeMount() {
    this.$store.state.isTransparent = "bg-transparent";
  },
  mounted() {

    let user = JSON.parse(localStorage.getItem('user'));

    // Verificar si el usuario existe
    if (user) {
      this.getCategories();
      this.getCategoriesPaginated(1);
      this.getCollections();
      this.getCollectionsPaginated(1);
      this.getColors();
      this.getOficios();
      this.getBodegas();
      this.getTallas();

      // Refrescar la tabla paginada cada vez que se abra el modal de categorías
      const categoryModalEl = document.getElementById('ModalCategory');
      if (categoryModalEl) {
        categoryModalEl.addEventListener('shown.bs.modal', () => {
          this.getCategories();
          this.getCategoriesPaginated(this.categoryPage.current_page || 1);
        });
      }

      // Refrescar la tabla paginada cada vez que se abra el modal de colecciones
      const collectionModalEl = document.getElementById('ModalCollection');
      if (collectionModalEl) {
        collectionModalEl.addEventListener('shown.bs.modal', () => {
          this.getCollections();
          this.getCollectionsPaginated(this.collectionPage.current_page || 1);
        });
      }
    } else {
      console.log("No se encontró un usuario en el localStorage.");
      // Opcional: redirigir al login o mostrar un mensaje
    }
  }
};
</script>
